contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
        require(address(this).balance >= 0);
    }

    function run(uint unlockTime, uint deposit, uint amount) public payable {
        require(address(this).balance >= deposit);

        c.Put{value: deposit}(unlockTime);

        (uint u0, uint b0) = c.Acc(address(this));
        uint minSum = c.MinSum();
        uint nowTs = block.timestamp;

        bool reverted;
        try c.Collect(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool shouldSucceed = b0 >= minSum && b0 >= amount && nowTs > u0;
        (uint u1, uint b1) = c.Acc(address(this));

        if (shouldSucceed) {
            assert(!reverted);
            assert(b1 == b0 - amount);
            assert(u1 == u0);
        } else {
            assert(reverted);
            assert(b1 == b0);
            assert(u1 == u0);
        }
    }

    receive() external payable {}
}

