pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C(address(new Log()));
    }

    function _run(uint256 _unlockTime, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeUnlock;
        uint256 beforeBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { beforeUnlock = __r0; beforeBalance = __r1; } catch { return; }
        try c.Put{value: amount}(_unlockTime) {} catch { return; }
        uint256 afterUnlock;
        uint256 afterBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { afterUnlock = __r0; afterBalance = __r1; } catch { return; }
        assertTrue(beforeBalance == 0 || afterBalance != 0);
    }

    function testFuzz_run(uint256 _unlockTime, uint256 amount) public {
        _run(_unlockTime, amount);
    }

    receive() external payable {}
}

